def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                cache_key = key(func, self, *args, **kwargs)
                if cache_key in cache:
                    return cache[cache_key]
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

import traceback

class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            stack = traceback.extract_tb(e.__traceback__)
            formatted_stack = []
            for i, frame in enumerate(stack):
                if i >= max_level:
                    break
                if frame.filename.startswith("<"):
                    continue
                formatted_stack.append(f"{frame.filename}:{frame.lineno} in {frame.name}")
                if len(formatted_stack) >= max_path_level:
                    break
            return f"{e.__class__.__name__}: {e}\n{'\n'.join(formatted_stack)}"
        except Exception as ex:
            return f"Error formatting exception: {ex}"

