def _legacy_mergeOrderings(orderings):
    merged = []
    seen = set()
    for ordering in orderings:
        for item in ordering:
            if item not in seen:
                merged.append(item)
                seen.add(item)
    return merged

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the inheritance relationships
    inheritance = {cls: set() for cls in classes}
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                inheritance[cls].add(base)

    # Find the minimal bases
    minimal = []
    for cls in classes:
        if not any(cls in inheritance[base] for base in minimal):
            minimal.append(cls)

    # Sort the minimal bases
    minimal.sort(key=classes.index)

    return minimal

