def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files or not digests_used:
        raise ValueError("Manifest files and digests used cannot be empty")

    for manifest_file in manifest_files:
        try:
            with open(manifest_file, 'r') as file:
                manifest_content = file.read()
                for digest in digests_used:
                    if digest not in manifest_content:
                        raise ValueError(f"Digest {digest} not found in manifest file {manifest_file}")
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file {manifest_file} not found")
        except Exception as e:
            raise Exception(f"Error processing manifest file {manifest_file}: {e}")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict) or 'versions' not in inventory:
        raise ValueError("Invalid inventory format")
    if not isinstance(version, str) or version not in inventory['versions']:
        raise ValueError("Invalid version")

    logical_path_map = {}
    for logical_path, file_info in inventory['versions'][version].items():
        if 'content_files' in file_info:
            logical_path_map[logical_path] = set(file_info['content_files'])

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, list) or not all(isinstance(f, str) for f in manifest_files):
        raise ValueError("Manifest files must be a list of strings")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    fixity_files = fixity['files']

    if not isinstance(fixity_files, list) or not all(isinstance(f, str) for f in fixity_files):
        raise ValueError("Files in fixity block must be a list of strings")

    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError(f"File {file} in fixity block is not listed in the manifest")

    return True

import os

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        return []
    except PermissionError:
        return []
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

