import re
import platform

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if platform.system() == 'posix' else 0

    if platform == 1:
        pattern = r'([^\s"]+|"([^"]*)")'
    elif platform == 0:
        pattern = r'([^\s"]+|"([^"]*)")'
    else:
        raise ValueError("Invalid platform value")

    return re.findall(pattern, s)

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.lower() == "seconds":
            return datetime.timedelta(seconds=number)
        elif unit.lower() == "minutes":
            return datetime.timedelta(minutes=number)
        elif unit.lower() == "hours":
            return datetime.timedelta(hours=number)
        elif unit.lower() == "days":
            return datetime.timedelta(days=number)
        elif unit.lower() == "weeks":
            return datetime.timedelta(weeks=number)
        elif unit.lower() == "months":
            return datetime.timedelta(days=number * 30)  # Approximation
        elif unit.lower() == "years":
            return datetime.timedelta(days=number * 365)  # Approximation
        else:
            raise ValueError(f"Unsupported time unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid frequency format: {frequency}")

