def load_configurations(config_filenames: List[str], overrides: Dict[str, str] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = eval(file.read(), overrides)
                if resolve_env:
                    config = resolve_environment_variables(config)
                config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None)
            log_records.append(log_record)

    return config_dict, log_records

def resolve_environment_variables(config: dict) -> dict:
    import os
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
            env_var = value[2:-1]
            config[key] = os.getenv(env_var, value)
        elif isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
        elif isinstance(value, list):
            config[key] = [resolve_environment_variables(item) if isinstance(item, dict) else item for item in value]
    return config

