def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    try:
        if not isinstance(timestr, str):
            raise TypeError("Non-string or character stream input")

        if tzinfos is not None:
            if not isinstance(tzinfos, (dict, callable)):
                raise TypeError("Invalid tzinfos type")

        dt = _parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)

        if ignoretz and dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)

        return dt
    except ParserError as e:
        raise ParserError(f"Invalid or unknown string format: {e}")
    except OverflowError as e:
        raise OverflowError(f"Parsed date exceeds the largest valid C integer: {e}")

