        raise Exception(f"Failed to retrieve NodeInfo document: {e}")

from typing import Dict
import json
from xml.etree import ElementTree as ET

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        if document.startswith('{'):
            # JSON format
            return json.loads(document)
        elif document.startswith('<'):
            # XRD format
            root = ET.fromstring(document)
            result = {}
            for link in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}link'):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    result[rel] = href
            return result
        else:
            raise ValueError("Invalid webfinger document format")
    except (json.JSONDecodeError, ET.ParseError) as e:
        raise ValueError(f"Error parsing webfinger document: {e}")

import requests
