    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not args:
        raise ValueError("No arguments provided")

    min_val = args.get('min')
    max_val = args.get('max')
    value = args.get('value')

    if min_val is None or max_val is None or value is None:
        raise ValueError("Missing required arguments: min, max, value")

    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)) or not isinstance(value, (int, float)):
        raise ValueError("min, max, and value must be numbers")

    if value < min_val or value > max_val:
